/* 1-Dars: Web rivojlanishi, Brauzerlar ishlashi va HTML ga kirish */
<!-- 1-Dars: HTML ga kirish -->
<h1>InFast Academy Frontend</h1>

/* 3-Dars: Matn bilan ishlash teglari: h1-h6, p, span, strong, em */
<h1>Sarlavha</h1>
<p><strong>Muhim matn</strong></p>

/* 14-Dars: CSS Selektorlar: Element, Class, ID va universal selektorlar */
.card {
  background-color: #f5f5f5;
}

/* 15-Dars: Ranglar bilan ishlash: HEX, RGB, HSL va Opacity/RGBA */
.box {
  color: rgba(0, 0, 0, 0.8);
}

/* 16-Dars: CSS Typography: font-family, font-size, font-weight, line-height */
body {
  font-family: 'Inter', sans-serif;
}

/* 17-Dars: Box Model tushunchasi: Content, Padding, Border, Margin */
.container {
  padding: 20px;
  margin: 0 auto;
}

/* 18-Dars: Box-Sizing xususiyati: content-box va border-box */
* {
  box-sizing: border-box;
}

/* 19-Dars: CSS Position xususiyati: static, relative, absolute, fixed, sticky */
.modal {
  position: fixed;
  top: 50%;
}

/* 20-Dars: CSS Display xususiyati: block, inline, inline-block, none */
.btn {
  display: inline-block;
}

/* 21-Dars: Overflow va z-index layer tushunchalari */
.drawer {
  z-index: 999;
  overflow-y: auto;
}

/* 22-Dars: CSS Pseudo-classlar: :hover, :active, :nth-child, :first-child */
button:hover {
  background: #007bff;
}

/* 23-Dars: CSS Pseudo-elementlar: ::before, ::after va content xususiyati */
.title::after {
  content: '';
  display: block;
}

/* 24-Dars: CSS Variables (Custom Properties): --primary-color va var() */
:root {
  --primary: #3b82f6;
}
.btn { background: var(--primary); }

/* 25-Dars: CSS Flexbox asoslari: display: flex, justify-content, align-items */
.row {
  display: flex;
  justify-content: space-between;
}

/* 26-Dars: CSS Flexbox yo'nalishlari: flex-direction, flex-wrap, gap */
.grid-row {
  flex-direction: row;
  gap: 16px;
}

/* 27-Dars: CSS Grid Layout: display: grid, grid-template-columns, fr birligi */
.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

/* 28-Dars: CSS Grid gap, grid-area va Responsive Grid layoutlar */
.layout {
  grid-gap: 20px;
}

/* 29-Dars: Responsive Web Design: Media Queries (@media screen) */
@media (max-width: 768px) {
  .container { flex-direction: column; }
}

/* 30-Dars: Mobile-First va Desktop-First dizayn yondashuvlari */
@media (min-width: 1024px) {
  .sidebar { display: block; }
}

/* 31-Dars: CSS Transitions, Transform (scale, rotate, translate) va Animation */
.card {
  transition: transform 0.3s ease;
}
.card:hover { transform: translateY(-5px); }

/* 32-Dars: CSS Keyframes animatsiyalari (@keyframes) */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* 33-Dars: Figma Dasturi: Dizayn maketlarini ko'rish, dev mode va CSS qiymatlarni olish */
<!-- Figma layout elementini qayta yaratish -->
<div className="figma-card"></div>

/* 34-Dars: Figma Auto Layout, Components va Design System tushunchalari */
.design-system {
  --primary: #3b82f6;
}

/* 36-Dars: Git Branching, Merging va Merge Conflicts bilan ishlash */
git checkout -b feature/login
git merge feature/login

/* 37-Dars: GitHub bilan ishlash: Remote repository yaratish, git push, git pull */
git remote add origin https://github.com/user/repo.git
git push -u origin main

/* 41-Dars: O'zgaruvchilar: var, let va const farqlari hamda Hoisting */
let age = 20;
const name = 'Sardor';

/* 42-Dars: Ma'lumot turlari: Primitive (string, number, boolean, null, undefined) va Reference */
const isStudent = true;
const price = 99.99;

/* 45-Dars: Switch Case strukturasi va ko'p shartli tanlovlar */
switch(day) {
  case 1: console.log('Dushanba'); break;
}

/* 46-Dars: Sikllar: for, while va do...while sikllari */
for (let i = 0; i < 5; i++) {
  console.log(i);
}

/* 47-Dars: Funksiyalar: Function Declaration vs Function Expression */
function greet(name) {
  return `Hello ${name}`;
}

/* 49-Dars: Scope: Global, Function va Block scope tushunchalari */
if (true) {
  let blockVar = 'Inside';
}

/* 50-Dars: Closures (Yopiq funksiyalar) va Lexical Environment */
function outer() {
  let count = 0;
  return () => ++count;
}

/* 52-Dars: Array (Massivlar) asoslari: push, pop, shift, unshift, length */
const arr = [1, 2, 3];
arr.push(4);

/* 55-Dars: Object (Obyektlar) asoslari: Key-Value, dot vs bracket notation */
const user = { name: 'Ali', age: 25 };
console.log(user.name);

/* 57-Dars: Destructuring Assignment: Massiv va Obyektlarni destrukturizatsiya qilish */
const { name, age } = user;
const [first, second] = arr;

/* 62-Dars: Try...Catch xatoliklarni ushlash va Custom Error otish (throw) */
try {
  throw new Error('Something went wrong');
} catch (err) {
  console.error(err.message);
}

/* 63-Dars: ES6+ Modullari: import va export default / named exports */
export const add = (a, b) => a + b;
import { add } from './math.js';

/* 66-Dars: DOM Elementlarini tahrirlash: textContent, innerHTML, style */
element.textContent = 'Yangi Matn';
element.style.color = 'red';

/* 69-Dars: Form Eventlari va e.preventDefault() bilan sahifa yangilanishini to'xtatish */
form.addEventListener('submit', (e) => {
  e.preventDefault();
});

/* 70-Dars: DOM elementlarini dynamically yaratish va o'chirish: createElement, appendChild, remove */
const div = document.createElement('div');
document.body.appendChild(div);

/* 73-Dars: Async / Await sintaksisi va asinxron koding jozibadorligi */
async function getData() {
  const res = await fetch(url);
}

/* 74-Dars: Fetch API va HTTP So'rovlar (GET, POST, PUT, DELETE) */
const res = await fetch('https://api.example.com/data');
const data = await res.json();

/* 77-Dars: Single Page Application (SPA) va React.js nimaga kerak? */
// Single Page Application Concept
const spa = true;

/* 78-Dars: Vite yordamida React loyihasini yaratish va loyiha strukturasi */
import { useState } from 'react';
import React from 'react';

/* 80-Dars: React Components: Functional Components yaratish */
export function Header() {
  return <header>Navbar</header>;
}

/* 81-Dars: Props tushunchasi: Komponentlarga ma'lumot uzatish */
function UserCard({ name, role }) {
  return <div>{name} - {role}</div>;
}

/* 82-Dars: Children prop va Komponentlarni bir-birining ichiga joylash */
function Container({ children }) {
  return <div className="wrapper">{children}</div>;
}

/* 87-Dars: Forms React-da: Controlled Inputs va State bog'lash */
const [text, setText] = useState('');
<input value={text} onChange={e => setText(e.target.value)} />

/* 88-Dars: useEffect hook: Side effects va Component Lifecycle (Mount, Update, Unmount) */
useEffect(() => {
  console.log('Mounted');
}, []);

/* 89-Dars: useEffect va Fetch API: Serverdan ma'lumotlarni yuklash va Loading state */
useEffect(() => {
  fetch('/api').then(res => res.json()).then(setData);
}, []);

/* 90-Dars: useRef hook: DOM elementlariga to'g'ridan-to'g'ri murojaat va Mutable qiymatlar */
const inputRef = useRef(null);
inputRef.current.focus();

/* 91-Dars: Custom Hooks: O'zimizning takrorlanuvchi hooklarimizni yaratish */
function useFetch(url) {
  const [data, setData] = useState(null);
  return { data };
}

/* 96-Dars: React Router v6: createBrowserRouter, RouterProvider va Routes/Route */
import { BrowserRouter, Routes, Route } from 'react_router_dom';
<Route path="/" element={<Home />} />

/* 97-Dars: React Router: Link, NavLink, useNavigate va sahifalar o'rtasida o'tish */
const navigate = useNavigate();
navigate('/dashboard');

/* 99-Dars: Nested Routes va Outlet obyekti orqali layout yaratish */
function DashboardLayout() {
  return <div><Sidebar /><Outlet /></div>;
}

/* 101-Dars: Shadcn UI / Lucide-react: Zamonaviy komponentlar kutubxonasi */
import { Button } from '@/components/ui/button';
import { Layers } from 'lucide-react';

/* 102-Dars: Form Validation React-da: React Hook Form va Zod sxemasi */
import { useForm } from 'react-hook-form';
const { register, handleSubmit } = useForm();

/* 103-Dars: State Management tushunchasi: Local State vs Global State */
// Global State Management Concept
const globalState = true;

/* 104-Dars: Zustand o'rnatish va sodda global store yaratish */
import { create } from 'zustand';
const useStore = create(set => ({ count: 0, inc: () => set(state => ({ count: state.count + 1 })) }));

/* 105-Dars: Redux Toolkit (RTK) asoslari: configureStore, createSlice */
import { createSlice } from '@reduxjs.log/toolkit';
const userSlice = createSlice({ name: 'user', initialState: {}, reducers: {} });

/* 106-Dars: Redux Provider va useSelector, useDispatch hooklari */
const dispatch = useDispatch();
const user = useSelector(state => state.user);

/* 108-Dars: Axios kutubxonasi va Axios Instance (interceptors) yaratish */
import axios from 'axios';
const api = axios.create({ baseURL: 'https://api.example.com' });

/* 110-Dars: Fullstack API Integration: JWT Auth (Login/Register) oqimi */
const handleLogin = async (credentials) => {
  const res = await api.post('/auth/login', credentials);
};

/* 111-Dars: Error Boundary va Fallback UI tayyorlash */
// Error Boundary Component
const hasError = false;

/* 112-Dars: Production Build Optimizatsiyasi (npm run build) va bundle analizi */
// Production build optimization check
const isProduction = true;

/* 113-Dars: Vercel va Netlify platformalariga Frontend ilovani bepul joylashtirish (Deploy) */
// Vercel Deployment configuration
const deployed = true;
